def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_last, op_last = history[-1]

    opp_def = 0
    for _, o in history:
        if o == 'D':
            opp_def += 1

    rec_opp_def = 0
    for _, o in history[-10:]:
        if o == 'D':
            rec_opp_def += 1

    streak_op_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_op_d += 1
        else:
            break

    streak_op_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            streak_op_c += 1
        else:
            break

    cd_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C' and history[i][1] == 'D':
            cd_streak += 1
        else:
            break

    start = n - 12
    if start < 0:
        start = 0

    d_next = 0
    d_to_c = 0
    for i in range(start, n - 1):
        if history[i][0] == 'D':
            d_next += 1
            if history[i + 1][1] == 'C':
                d_to_c += 1

    resp_d_c = d_to_c / d_next if d_next else 0.0

    hostile = (
        opp_def >= max(4, int(n * 0.45)) or
        (n >= 8 and rec_opp_def >= 7) or
        (n >= 2 and opp_def == n) or
        (streak_op_d >= 5 and opp_def >= 5)
    )

    if op_last == 'D':
        if hostile:
            return 'D'

        if n >= 2 and my_last == 'C' and history[-2][0] == 'D' and opp_def <= max(3, int(n * 0.3)):
            return 'C'

        if opp_def <= max(1, n // 12):
            return 'C'

        if my_last == 'D':
            if rec_opp_def >= 7 or opp_def * 2 >= n:
                return 'D'
            return 'C'

        if streak_op_d >= 2 or cd_streak >= 2:
            return 'D'

        if rec_opp_def >= 4 and opp_def >= n * 0.25:
            return 'D'

        return 'C'

    if d_next > 0 and resp_d_c >= 0.5 and not hostile and opp_def <= max(6, int(n * 0.4)):
        return 'D'

    if my_last == 'D':
        return 'C'

    if (n == 25 or n == 55 or n == 80) and not hostile:
        if streak_op_c >= 8 and opp_def <= max(4, int(n * 0.2)):
            if rng.random() < 0.2:
                return 'D'

    if n >= 90 and not hostile and opp_def <= max(5, int(n * 0.25)) and resp_d_c >= 0.4:
        if rng.random() < 0.25:
            return 'D'

    return 'C'
